SELECT s.id, s.device, COUNT(we.id) AS web_event_count, SUM(CASE WHEN we.page = '/cart' THEN 1 ELSE 0 END) AS cart_count, SUM(CASE WHEN we.page = '/product' THEN we.duration_sec ELSE 0 END) AS product_duration_sec FROM sessions s LEFT OUTER JOIN web_events we ON we.session_id = s.id WHERE TO_DATE(we.event_time) < '2024-06-01' GROUP BY s.id, s.device ORDER BY cart_count, id, device LIMIT 50;
